		"viz_ts_hdr_title": {
			"type": "splunk.markdown",
			"options": {
				"markdown": "## Search Health & Troubleshooting\n*Cache performance, search concurrency, and schedule analysis*"
			}
		},
		"viz_ts_section": {
			"type": "splunk.rectangle",
			"options": {
				"fillColor": "rgba(255,255,255,0.45)",
				"strokeColor": "rgba(0,0,0,0.06)",
				"rx": 12
			}
		},
		"viz_ts_kpi_total": {
			"type": "splunk.singlevalue",
			"dataSources": {
				"primary": "ds_kpi_total"
			},
			"options": {
				"majorColor": "#049fd9"
			},
			"title": "Total Searches",
			"description": "All search dispatches across dashboards"
		},
		"viz_ts_kpi_scheduled": {
			"type": "splunk.singlevalue",
			"dataSources": {
				"primary": "ds_kpi_scheduled"
			},
			"options": {
				"majorColor": "#049fd9"
			},
			"title": "Scheduled",
			"description": "Searches triggered by a saved schedule"
		},
		"viz_ts_kpi_ondemand": {
			"type": "splunk.singlevalue",
			"dataSources": {
				"primary": "ds_kpi_ondemand"
			},
			"options": {
				"majorColor": "#E5A823"
			},
			"title": "On-Demand",
			"description": "Searches triggered by user interaction"
		},
		"viz_ts_kpi_pct": {
			"type": "splunk.singlevalue",
