		"viz_ts_box_detail": {
			"type": "splunk.rectangle",
			"options": {
				"fillColor": "rgba(255,255,255,0.78)",
				"strokeColor": "rgba(0,0,0,0.08)",
				"rx": 10
			}
		},
		"viz_ts_detail_table": {
			"type": "splunk.table",
			"dataSources": {
				"primary": "ds_cache_detail"
			},
			"options": {
				"count": 50,
				"columnFormat": {
					"Cache Status": {
						"rowColors": "> table | seriesByName(\"Cache Status\") | matchValue(Cache_Status_RowColorsEditorConfig)",
						"rowBackgroundColors": "> table | seriesByName(\"Cache Status\") | matchValue(Cache_Status_RowBgColorsEditorConfig)"
					},
					"Run (sec)": {
						"rowColors": "> table | seriesByName('Run (sec)') | rangeValue(Run__sec_RowColorsEditorConfig)",
						"rowBackgroundColors": "> table | seriesByName('Run (sec)') | rangeValue(Run__sec_RowBgColorsEditorConfig)"
					},
					"Schedule": {
						"rowColors": "> table | seriesByName(\"Schedule\") | matchValue(Schedule_RowColorsEditorConfig)",
						"rowBackgroundColors": "> table | seriesByName(\"Schedule\") | matchValue(Schedule_RowBgColorsEditorConfig)"
					},
					"Age (min)": {
						"rowColors": "> table | seriesByName('Age (min)') | rangeValue(Age__min_RowColorsEditorConfig)"
					}
				},
				"fontSize": "small"
			},
			"context": {
				"Cache_Status_RowColorsEditorConfig": [
					{
						"match": "CACHE HIT",
						"value": "#6EBE4A"
					},
					{
						"match": "CACHE MISS",
						"value": "#D64550"
					}
				],
				"Cache_Status_RowBgColorsEditorConfig": [
					{
						"match": "CACHE HIT",
						"value": "#E5F5FC"
					},
					{
						"match": "CACHE MISS",
						"value": "#E5F5FC"
					}
				],
				"Run__sec_RowColorsEditorConfig": [
					{
						"to": 1,
						"value": "#6EBE4A"
					},
					{
						"from": 1,
						"to": 5,
						"value": "#6EBE4A"
					},
					{
						"from": 5,
						"to": 10,
						"value": "#E5A823"
					},
					{
						"from": 10,
						"to": 60,
						"value": "#E5A823"
					},
					{
						"from": 60,
						"value": "#D64550"
					}
				],
				"Run__sec_RowBgColorsEditorConfig": [
					{
						"to": 1,
						"value": "#E5F5FC"
					},
					{
						"from": 1,
						"to": 5,
						"value": "#E5F5FC"
					},
					{
						"from": 5,
						"to": 10,
						"value": "#E5F5FC"
					},
					{
						"from": 10,
						"to": 60,
						"value": "#E5F5FC"
					},
					{
						"from": 60,
						"value": "#E5F5FC"
					}
				],
				"Schedule_RowColorsEditorConfig": [
					{
						"match": "INLINE",
						"value": "#D64550"
					},
					{
						"match": "NOT SCHEDULED",
						"value": "#D64550"
					}
				],
