		"viz_ts_cache_pie": {
			"type": "splunk.pie",
			"dataSources": {
				"primary": "ds_cache_pie"
			},
			"title": "Cache Hit vs Miss",
			"options": {
				"seriesColors": [
					"#6EBE4A",
