		"viz_ts_sched_pie": {
			"type": "splunk.pie",
			"dataSources": {
				"primary": "ds_sched_pie"
			},
			"title": "Scheduled vs On-Demand",
			"options": {
				"seriesColors": [
					"#049fd9",
