		"ds_cache_summary": {
			"name": "Cache Hit Summary",
			"options": {
				"query": "| rest /services/search/jobs splunk_server=local\n| search (provenance=\"UI:dashboard:*\") NOT provenance=\"UI:dashboard:admin_guide\" | eval is_hit = if(match(sid, \"^scheduler__\"), 1, 0)\n| eval dashboard_id = case(\n match(provenance, \"^UI:dashboard:\"), replace(provenance, \"^UI:dashboard:\", \"\"),\n match(label, \"^Executive Dashboard\"), \"home_launchpad\",\n match(label, \"^Executive Summary\"), \"home_launchpad\",\n match(label, \"^Security Resilience\"), \"security\",\n match(label, \"^IT - Critical\"), \"it_health\",\n match(label, \"^Asset Inventory\"), \"asset_inventory\",\n match(label, \"^Building\"), \"building\",\n match(label, \"^Statewide\"), \"statewide_exercise\",\n match(label, \"^Client Summary\"), \"statewide_exercise\",\n 1==1, \"unknown\")\n| eval search_name = if(isnotnull(label) AND label!=\"\", label, \"(inline search)\")\n| join type=left dashboard_id\n [| rest /servicesNS/-/-/data/ui/views splunk_server=local\n | search eai:acl.app=\"splunk-cisco-dashboards\"\n | rename title as dashboard_id, label as dashboard_label\n | table dashboard_id, dashboard_label]\n| eval Dashboard = if(isnotnull(dashboard_label), dashboard_label, dashboard_id)\n| dedup Dashboard, search_name\n| stats count as Total,\n sum(is_hit) as \"Cache Hits\",\n sum(eval(if(is_hit=0,1,0))) as \"Cache Misses\",\n avg(is_hit) as hit_rate\n by Dashboard\n| eval \"Hit Rate %\" = round(hit_rate*100, 1)\n| fields - hit_rate\n| eval Summary = 'Cache Hits'.\"/\".Total.\" cached (\".'Hit Rate %'.\"%)\"\n| sort - \"Hit Rate %\"\n| table Dashboard, Total, \"Cache Hits\", \"Cache Misses\", \"Hit Rate %\", Summary"
			},
			"type": "ds.search"
		},
		"ds_cache_detail": {
			"name": "Cache Hit Detail",
			"options": {
				"query": "| rest /services/search/jobs splunk_server=local\n| search (provenance=\"UI:dashboard:*\") NOT provenance=\"UI:dashboard:admin_guide\" | eval cache_status = if(match(sid, \"^scheduler__\"), \"CACHE HIT\", \"CACHE MISS\")\n| eval dashboard_id = case(\n match(provenance, \"^UI:dashboard:\"), replace(provenance, \"^UI:dashboard:\", \"\"),\n match(label, \"^Executive Dashboard\"), \"home_launchpad\",\n match(label, \"^Executive Summary\"), \"home_launchpad\",\n match(label, \"^Security Resilience\"), \"security\",\n match(label, \"^IT - Critical\"), \"it_health\",\n match(label, \"^Asset Inventory\"), \"asset_inventory\",\n match(label, \"^Building\"), \"building\",\n match(label, \"^Statewide\"), \"statewide_exercise\",\n match(label, \"^Client Summary\"), \"statewide_exercise\",\n 1==1, \"unknown\")\n| eval dispatched_by = case(\n match(sid, \"^scheduler__\"), \"scheduler\",\n isnotnull(request.ui_dispatch_app), author,\n 1==1, author)\n| eval search_name = if(isnotnull(label) AND label!=\"\", label, \"(inline search)\")\n| eval run_seconds = round(runDuration, 2)\n| eval age_minutes = round((now() - strptime(published, \"%Y-%m-%dT%H:%M:%S.%3N%:z\")) / 60, 1)\n| eval last_run = strftime(strptime(published, \"%Y-%m-%dT%H:%M:%S.%3N%:z\"), \"%a %b %d %I:%M%p\")\n| join type=left search_name\n [| rest /servicesNS/-/-/saved/searches splunk_server=local\n| search eai:acl.app=\"splunk-cisco-dashboards\"\n | eval search_name = title\n | eval schedule = if(is_scheduled=\"1\", cron_schedule, \"NOT SCHEDULED\")\n | table search_name, schedule]\n| join type=left dashboard_id\n [| rest /servicesNS/-/-/data/ui/views splunk_server=local\n | search eai:acl.app=\"splunk-cisco-dashboards\"\n | rename title as dashboard_id, label as dashboard_label\n | table dashboard_id, dashboard_label]\n| eval Dashboard = if(isnotnull(dashboard_label), dashboard_label, dashboard_id)\n| fillnull value=\"INLINE\" schedule\n| stats latest(cache_status) as \"Cache Status\",\n latest(schedule) as Schedule,\n latest(dispatched_by) as \"Dispatched By\",\n latest(run_seconds) as \"Run (sec)\",\n latest(age_minutes) as \"Age (min)\",\n latest(last_run) as \"Last Run\"\n by Dashboard, search_name\n| rename search_name as \"Saved Search\"\n| sort Dashboard, \"Cache Status\", \"Saved Search\"\n| table Dashboard, \"Saved Search\", \"Cache Status\", Schedule, \"Dispatched By\", \"Run (sec)\", \"Age (min)\", \"Last Run\" "
			},
			"type": "ds.search"
		},
		"ds_slowest_searches": {
			"name": "Slowest Searches",
			"type": "ds.search",
			"options": {
				"query": "| rest /services/search/jobs splunk_server=local\n| search (provenance=\"UI:dashboard:*\") NOT provenance=\"UI:dashboard:admin_guide\"\n| eval run_seconds = round(runDuration, 2)\n| eval last_run = strftime(strptime(published, \"%Y-%m-%dT%H:%M:%S.%3N%:z\"), \"%a %b %d %I:%M%p\")\n| stats latest(run_seconds) as \"Run (sec)\", latest(last_run) as \"Last Run\" by label\n| sort 10 - \"Run (sec)\"\n| rename label as search_name\n| join type=left search_name\n [| makeresults count=116\n| streamstats count as row\n| eval search_name = case(\n row==1, \"Asset Inventory - ds_gap_analysis\",\n row==2, \"Building Resilience - ds_compliance_detail\",\n row==3, \"Building Resilience - ds_device_presence_trend\",\n row==4, \"Building Resilience - ds_room_detail\",\n row==5, \"Building Resilience - ds_spaces_location_breakdown\",\n row==6, \"Building Resilience - ds_ssid_clients\",\n row==7, \"Building Resilience - ds_ssid_trend\",\n row==8, \"Building Resilience - ds_user_presence_trend\",\n row==9, \"Building Resilience - ds_webex_devices\",\n row==10, \"Building Resilience - ds_webex_people_trend\",\n row==11, \"Client Summary - ds_client_by_band\",\n row==12, \"Client Summary - ds_client_by_device_type\",\n row==13, \"Client Summary - ds_client_by_location\",\n row==14, \"Client Summary - ds_client_by_protocol\",\n row==15, \"Client Summary - ds_client_by_ssid\",\n row==16, \"Client Summary - ds_client_count_over_time\",\n row==17, \"Client Summary - ds_client_health_by_location\",\n row==18, \"Client Summary - ds_client_health_dist\",\n row==19, \"Client Summary - ds_client_health_kpi\",\n row==20, \"Client Summary - ds_client_onboarding\",\n row==21, \"Client Summary - ds_client_os_dist\",\n row==22, \"Client Summary - ds_top_clients_by_usage\",\n row==23, \"Client Summary - ds_wireless_vs_wired\",\n row==24, \"Executive Dashboard - Data Status Pipeline\",\n row==25, \"Executive Dashboard - Score Pipeline\",\n row==26, \"Executive Dashboard - ds_active_clients\