		"ds_avg_runtime": {
			"name": "Avg Runtime by Dashboard",
			"type": "ds.search",
			"options": {
				"query": "| rest /services/search/jobs splunk_server=local\n| search (provenance=\"UI:dashboard:*\") NOT provenance=\"UI:dashboard:admin_guide\" | eval dashboard_id = case(\n match(provenance, \"^UI:dashboard:\"), replace(provenance, \"^UI:dashboard:\", \"\"),\n match(label, \"^Executive Dashboard\"), \"home_launchpad\",\n match(label, \"^Executive Summary\"), \"home_launchpad\",\n match(label, \"^Security Resilience\"), \"security\",\n match(label, \"^IT - Critical\"), \"it_health\",\n match(label, \"^Asset Inventory\"), \"asset_inventory\",\n match(label, \"^Building\"), \"building\",\n match(label, \"^Statewide\"), \"statewide_exercise\",\n match(label, \"^Client Summary\"), \"statewide_exercise\",\n 1==1, \"unknown\")\n| join type=left dashboard_id\n [| rest /servicesNS/-/-/data/ui/views splunk_server=local\n | search eai:acl.app=\"splunk-cisco-dashboards\"\n | rename title as dashboard_id, label as dashboard_label\n | table dashboard_id, dashboard_label]\n| eval Dashboard = if(isnotnull(dashboard_label), dashboard_label, dashboard_id)\n| stats avg(runDuration) as avg_sec, max(runDuration) as max_sec, count as total_searches by Dashboard\n| eval \"Avg (sec)\" = round(avg_sec, 2), \"Max (sec)\" = round(max_sec, 2)\n| rename total_searches as Searches\n| sort - \"Avg (sec)\"\n| table Dashboard, Searches, \"Avg (sec)\", \"Max (sec)\" "
			}
		},
		"ds_schedule_conflicts": {
			"name": "Schedule Conflicts",
			"type": "ds.search",
			"options": {
				"query": "| rest /servicesNS/-/-/saved/searches splunk_server=local\n| search eai:acl.app=\"splunk-cisco-dashboards\" | search is_scheduled=\"1\"\n| eval search_name = title\n| stats count as searches, values(search_name) as \"Saved Searches\" by cron_schedule\n| where searches > 1\n| sort - searches\n| rename cron_schedule as \"Cron Schedule\", searches as \"Concurrent Searches\"\n| table \"Cron Schedule\", \"Concurrent Searches\", \"Saved Searches\" "
			}
		},
		"ds_concurrency_kpis": {
			"name": "Concurrency KPIs",
			"type": "ds.search",
			"options": {
				"query": "| rest /servicesNS/-/-/saved/searches splunk_server=local\n| search eai:acl.app=\"splunk-cisco-dashboards\" | stats count as total_searches,\n sum(eval(if(is_scheduled=\"1\", 1, 0))) as scheduled,\n sum(eval(if(is_scheduled=\"0\" OR is_scheduled=\"\", 1, 0))) as on_demand\n| eval scheduled_pct = round(scheduled / total_searches * 100, 0)\n| table total_searches, scheduled, on_demand, scheduled_pct"
			}
		},
		"ds_dashboard_views": {
			"name": "Dashboard Views",
			"type": "ds.search",
			"options": {
				"query": "index=_internal sourcetype=splunk_web_access file=shareddashboard id=*\n| join type=left id\n [| rest /servicesNS/-/-/data/ui/views splunk_server=local\n | search eai:acl.app=\"splunk-cisco-dashboards\"\n | rename title as id, label as dashboard_label\n | table id, dashboard_label]\n| eval Dashboard = if(isnotnull(dashboard_label), dashboard_label, id)\n| eval browser = case(\n match(useragent, \"Chrome\"), \"Chrome\",\n match(useragent, \"Safari\"), \"Safari\",\n match(useragent, \"Firefox\"), \"Firefox\",\n match(useragent, \"Edge\"), \"Edge\",\n 1==1, \"Other\")\n| stats count as Views,\n dc(oid) as \"Unique Sessions\",\n values(browser) as Browsers,\n latest(_time) as last_seen\n by Dashboard\n| eval \"Last Seen\" = strftime(last_seen, \"%a %b %d %I:%M%p\")\n| fields - last_seen\n| sort - Views\n| table Dashboard, Views, \"Unique Sessions\", Browsers, \"Last Seen\" ",
				"queryParameters": {
					"earliest": "-7d@d",
					"latest": "now"
				}
			}
		},
		"ds_cache_pie": {
			"name": "Cache Hit vs Miss (Overall)",
			"type": "ds.search",
			"options": {
				"query": "| rest /services/search/jobs splunk_server=local\n| search (provenance=\"UI:dashboard:*\") NOT provenance=\"UI:dashboard:admin_guide\" | eval status = if(match(sid, \"^scheduler__\"), \"Cache Hit\", \"Cache Miss\")\n| stats count by status"
			}
		},
		"ds_runtime_bar": {
			"name": "Runtime by Search (Top 10)",
			"type": "ds.search",
			"options": {
				"query": "| rest /services/search/jobs splunk_server=local\n| search (provenance=\"UI:dashboard:*\") NOT provenance=\"UI:dashboard:admin_guide\" | stats latest(runDuration) as runtime by label\n| eval runtime = round(runtime, 2)\n| sort 10 - runtime\n| rename label as search_name\n| table search_name, runtime"
			}
		},
		"ds_schedule_advisor": {
			"name": "Schedule Health Advisor",
			"type": "ds.search",
			"options": {
				"query": "| rest /servicesNS/-/-/saved/searches splunk_server=local\n| search eai:acl.app=\"splunk-cisco-dashboards\"\n| eval search_name = title\n| join type=left search_name\n [| search index=_audit action=search info=completed savedsearch_name!=\"\" earliest=-7d latest=now\n | stats latest(total_run_time) as last_runtime by savedsearch_name\n | rename savedsearch_name as search_name]\n| join type=left search_name\n [| rest /services/search/jobs splunk_server=local count=0\n | search label!=\"\"\n | eval search_name = label\n | stats latest(runDuration) as job_runtime by search_name]\n| eval last_runtime = round(coalesce(last_runtime, job_runtime), 1)\n| eval current_schedule = if(is_scheduled=\"1\", cron_schedule, \"NOT SCHEDULED\")\n| eval suggested_schedule = case(\n match(title, \"(?i)(trend|timechart|history)\"), \"7 */12 * * *\",\n match(title, \"(?i)(detail|table|inventory|gap)\"), \"22 */6 * * *\",\n match(title, \"(?i)(status|pipeline|score|health|kpi)\"), \"37 */4 * * *\",\n 1==1, \"52 */4 * * *\")\n| eval suggested_reason = case(\n is_scheduled!=\"1\", \"Not scheduled — enable via Settings > Searches, Reports, and Alerts > Edit Schedule\",\n match(cron_schedule, \"^\\*/[1-9] \"), \"Schedule too aggressive — stagger to reduce concurrency\",\n last_runtime > 120 AND match(cron_schedule, \"^\\*/[1-9] \"), \"Runs > 2 min on a tight schedule — reduce frequency\",\n 1==1, \"OK\")\n| where suggested_reason != \"OK\"\n| sort - last_runtime\n| rename search_name as \"Saved Search\", current_schedule as \"Current\", last_runtime as \"Runtime (sec)\", suggested_schedule as \"Suggested\", suggested_reason as \"Action\"\n| table \"Saved Search\", \"Current\", \"Runtime (sec)\", \"Suggested\", \"Action\" "
			}
		},
		"ds_sched_pie": {
			"name": "Scheduled vs On-Demand",
			"type": "ds.search",
			"options": {
				"query": "| rest /servicesNS/-/-/saved/searches splunk_server=local\n| search eai:acl.app=\"splunk-cisco-dashboards\" | eval type = if(is_scheduled=\"1\", \"Scheduled\", \"On-Demand\")\n| stats count by type"
			}
		},
		"ds_sourcetype_macro": {
			"name": "Sourcetype-to-Macro Reference",
			"type": "ds.search",
			"options": {
				"query": "| makeresults count=12\n| streamstats count as row\n| eval Macro = case(\n row==1, \"index_catalyst\",\n row==2, \"index_firewall\",\n row==3, \"index_identity\",\n row==4, \"index_windows\",\n row==5, \"index_network\",\n row==6, \"index_security\",\n row==7, \"index_meraki\",\n row==8, \"index_spaces\",\n row==9, \"index_thousandeyes\",\n row==10, \"index_bms\",\n row==11, \"index_dhcp\",\n row==12, \"index_f5\")\n| eval Sourcetypes = case(\n row==1, \"cisco:dnac:*\",\n row==2, \"cisco:asa, cisco:ftd, cisco:sfw:estreamer, cisco:estreamer:data, cisco:firepower:syslog\",\n row==3, \"cisco:ise:syslog\",\n row==4, \"XmlWinEventLog, ActiveDirectory, MSAD:NT6:DNS\",\n row==5, \"cisco:ios\",\n row==6, \"cisco:xdr:*, cisco:cloud_security:*, cisco:esa:*, cisco:wsa:*, cisco:sdwan:utd:logs, ms:defender:*\",\n row==7, \"meraki:*\",\n row==8, \"cisco:spaces:*\",\n row==9, \"cisco:thousandeyes:*\",\n row==10, \"bms:*\",\n row==11, \"DhcpSrvLog\",\n row==12, \"f5:bigip:*\")\n| eval Technology = case(\n row==1, \"Catalyst Center (DNAC)\",\n row==2, \"ASA / FTD / Firepower\",\n row==3, \"Cisco ISE\",\n row==4, \"Windows / Active Directory\",\n row==5, \"IOS Syslog\",\n row==6, \"XDR / Umbrella / ESA / WSA / SD-WAN / Defender\",\n row==7, \"Meraki Dashboard\",\n row==8, \"Cisco Spaces\",\n row==9, \"ThousandEyes\",\n row==10, \"Building Management System\",\n row==11, \"Windows DHCP Server\",\n row==12, \"F5 BIG-IP\")\n| table Macro, Sourcetypes, Technology"
			}
		},
		"ds_kpi_total": {
			"name": "KPI Total Searches",
			"type": "ds.chain",
			"options": {
				"extend": "ds_concurrency_kpis",
				"query": "| fields total_searches"
			}
		},
		"ds_kpi_scheduled": {
			"name": "KPI Scheduled",
			"type": "ds.chain",
			"options": {
				"extend": "ds_concurrency_kpis",
				"query": "| fields scheduled"
			}
		},
		"ds_kpi_ondemand": {
			"name": "KPI On-Demand",
			"type": "ds.chain",
			"options": {
				"extend": "ds_concurrency_kpis",
				"query": "| fields on_demand"
			}
		},
		"ds_kpi_pct": {
			"name": "KPI Scheduled %",
			"type": "ds.chain",
			"options": {
				"extend": "ds_concurrency_kpis",
				"query": "| fields scheduled_pct"
			}
		},
		"ds_dashboard_usage": {
			"type": "ds.search",
			"options": {
				"query": "index=_internal sourcetype=splunk_web_access user!=\"-\" app=* view=* \n| bin _time span=1d \n| stats dc(user) as daily_users values(user) as Users by _time, app, view \n| stats sparkline(sum(daily_users), 1d) as trend, dc(user) as \"Unique Users\", values(Users) as Users by app, view \n| rename app as App, view as Dashboard \n| sort - \"Unique Users\"",
				"queryParameters": {
					"earliest": "-30d@d",
					"latest": "now"
				}
			},
			"name": "Dashboard usage"
		}
	},
